\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Venue Color Theme (Hunger Crisis Advocacy - Dark/Warm) ──
\definecolor{primary}{HTML}{DC2626}     % red-600
\definecolor{secondary}{HTML}{D97706}   % amber-600
\definecolor{accent}{HTML}{EA580C}      % orange-600
\definecolor{bgposter}{HTML}{1C1917}    % stone-900 (muted dark)
\definecolor{cardbg}{HTML}{292524}      % stone-800
\definecolor{cardtitlebg}{HTML}{44403C} % stone-700
\definecolor{textdark}{HTML}{F9FAFB}    % white
\definecolor{textgray}{HTML}{D1D5DB}    % gray-300
\definecolor{stathighlight}{HTML}{451A03} % dark amber

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=36pt, itemsep=18pt, parsep=6pt, topsep=12pt,
  label={\color{secondary}$\blacktriangleright$}}

% ── Card styles (left accent stripe design) ──
\tcbset{
  darktheme/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    left=24pt, right=24pt, top=16pt, bottom=16pt,
    coltitle=textdark, colbacktitle=cardtitlebg,
    toptitle=12pt, bottomtitle=12pt,
    valign=top, drop shadow={opacity=0.3},
    coltext=textdark
  },
  redcard/.style={
    darktheme,
    borderline west={12pt}{0pt}{primary},
    fonttitle=\fontsize{44}{52}\selectfont\bfseries\color{primary},
    titlerule=3pt, titlerule style={primary!50},
  },
  bluecard/.style={
    darktheme,
    borderline west={12pt}{0pt}{accent},
    fonttitle=\fontsize{44}{52}\selectfont\bfseries\color{accent},
    titlerule=3pt, titlerule style={accent!50},
  },
  darkcard/.style={
    darktheme,
    borderline west={12pt}{0pt}{secondary},
    fonttitle=\fontsize{44}{52}\selectfont\bfseries\color{secondary},
    titlerule=3pt, titlerule style={secondary!50},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!40!black,
    borderline west={12pt}{0pt}{primary},
    left=24pt, right=24pt, top=16pt, bottom=16pt,
    fonttitle=\fontsize{44}{52}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary!80!black,
    toptitle=12pt, bottomtitle=12pt,
    valign=top, drop shadow={opacity=0.5},
    coltext=white
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=4mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=20pt, bottom=16pt,
  halign=center, valign=center,
  drop shadow={opacity=0.5}
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{100}{115}\selectfont\bfseries Hunger Doesn't Wait}\\[16pt]
  {\fontsize{85}{100}\selectfont\bfseries Together We Can End It}\\[16pt]
  {\fontsize{36}{44}\selectfont\color{white!80} A Call to Action for America's Hunger Crisis}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=12pt, bottom=12pt,
  valign=center, borderline south={4pt}{0pt}{primary!50},
]{name=stats, column=1, span=3, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{primary!60}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{80}{96}\selectfont\bfseries\color{primary} 48 MILLION}\\[8pt]
      {\fontsize{34}{40}\selectfont\color{textdark} People Facing Hunger}\vspace{12pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{accent!60}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{80}{96}\selectfont\bfseries\color{accent} 5.7 BILLION}\\[8pt]
      {\fontsize{34}{40}\selectfont\color{textdark} Meals Distributed}\vspace{12pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{secondary!60}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{80}{96}\selectfont\bfseries\color{secondary} 14 MILLION}\\[8pt]
      {\fontsize{34}{40}\selectfont\color{textdark} Children Affected}\vspace{12pt}%
    }}
  \end{minipage}
}

% ══ COLUMN 1 ══
\posterbox[redcard, title={The Hunger Crisis in America}
]{name=crisis, column=1, between=row5 and row12}{
  \fontsize{38}{48}\selectfont
  \begin{itemize}
    \item \textbf{An unfolding crisis} in every community across the United States.
    \item \textbf{Urban and rural alike:} families struggle to put nutritious food on the table.
    \item \textbf{Not just a statistic:} these are neighbors, classmates, and coworkers who need support \textit{right now}.
  \end{itemize}
}

\posterbox[bluecard, title={The Power of a Nationwide Network}
]{name=network, column=1, between=row12 and bottom}{
  \fontsize{38}{48}\selectfont
  \begin{itemize}
    \item \textbf{Feeding America} operates one of the nation's largest and most effective relief networks.
    \item \textbf{Moving food quickly}, safely, and reliably to the communities that need it most.
    \item \textbf{Rescued food} — perfectly good food that might go to waste — reaches people across all 50 states and Puerto Rico.
  \end{itemize}
}

% ══ COLUMN 2 ══
\posterbox[darkcard, title={Our Collective Impact}
]{name=impact, column=2, between=row5 and row12}{
  \fontsize{38}{48}\selectfont
  \vspace{8pt}
  \begin{center}
    \colorbox{primary!30}{\parbox{0.92\linewidth}{
      \centering\vspace{12pt}
      {\fontsize{54}{64}\selectfont\bfseries\color{white} 4.3 BILLION LBS}\\[6pt]
      {\fontsize{32}{40}\selectfont\color{textgray} of good food rescued from waste}
      \vspace{12pt}
    }}
  \end{center}
  \vspace{16pt}
  \begin{center}
    \colorbox{accent!30}{\parbox{0.92\linewidth}{
      \centering\vspace{12pt}
      {\fontsize{54}{64}\selectfont\bfseries\color{white} 60,000+}\\[6pt]
      {\fontsize{32}{40}\selectfont\color{textgray} free food programs operating}
      \vspace{12pt}
    }}
  \end{center}
  \vspace{16pt}
  \begin{center}
    \colorbox{secondary!30}{\parbox{0.92\linewidth}{
      \centering\vspace{12pt}
      {\fontsize{54}{64}\selectfont\bfseries\color{white} 200+}\\[6pt]
      {\fontsize{32}{40}\selectfont\color{textgray} food banks mobilized nationwide}
      \vspace{12pt}
    }}
  \end{center}
}

\posterbox[redcard, title={How We Unite Communities}
]{name=unite, column=2, between=row12 and bottom}{
  \fontsize{38}{48}\selectfont
  \begin{itemize}
    \item \textbf{Research-Driven Insights:}\\ Listening to neighbors shapes real solutions.
    \item \textbf{Local Relationships:}\\ Local wisdom turns into national action.
    \item \textbf{Nationwide Scale:}\\ Moving food reliably to where it is needed most.
    \item \textbf{Nutrition for Every Plate:}\\ Making healthy food accessible for fuller lives.
  \end{itemize}
}

% ══ COLUMN 3 ══
\posterbox[highlightcard, title={How You Can Make a Difference}
]{name=action, column=3, between=row5 and row15}{
  \fontsize{38}{48}\selectfont

  \begin{center}
    \colorbox{bgposter}{\parbox{0.92\linewidth}{
      \centering\vspace{16pt}
      {\fontsize{72}{84}\selectfont\bfseries\color{accent} \$1 = 10 MEALS}\\[8pt]
      {\fontsize{34}{44}\selectfont\color{white} Every dollar provides at least 10 meals\\to neighbors in need.}
      \vspace{16pt}
    }}
  \end{center}

  \vspace{16pt}
  \begin{itemize}
    \item \textbf{Donate:} Gifts are matched for a limited time to move fresh food fast.
    \item \textbf{Advocate:} Urge lawmakers to support community organizations.
    \item \textbf{Fundraise:} Inspire your community to make a collective difference.
    \item \textbf{Volunteer:} Sorting, packing, and distributing food takes your hands.
  \end{itemize}
}

\posterbox[darkcard, title={A Vision for the Future}
]{name=vision, column=3, between=row15 and bottom}{
  \fontsize{38}{48}\selectfont
  \begin{itemize}
    \item \textbf{Hunger touches every U.S. community,} but together, we can meet this moment.
    \item \textbf{Food rescue cannot wait.}
    \item \textbf{When communities unite} — through donations, advocacy, and volunteering — an America without hunger is within reach.
  \end{itemize}
}

\end{tcbposter}
\end{document}
EOF
